<input
  value={globalFilter ?? ""}
  onChange={(e) => table.setGlobalFilter(e.target.value)}
  placeholder="搜索..."
/>

// 表头单元格内的列筛选输入框（需 header.column.getCanFilter() 为 true）
{header.column.getCanFilter() ? (
